// src/update/check.ts
import { mkdtempSync as mkdtempSync3, rmSync as rmSync4 } from "fs";
import { tmpdir as tmpdir3 } from "os";
import { join as join14 } from "path";
var GIT_TIMEOUT_MS = 20000;
